    def minFlips(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])
        def flip(i, j):
            mat[i][j] ^= 1
            if i - 1 >= 0: mat[i - 1][j] ^= 1
            if i + 1 < m: mat[i + 1][j] ^= 1
            if j - 1 >= 0: mat[i][j - 1] ^= 1
            if j + 1 < n: mat[i][j + 1] ^= 1
        ans = 0
