class Solution:
    def solve(self, n, edges):
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        visited = [False] * n
        for i in range(n):
            if not visited[i]:
                visited[i] = True
                queue = [i]
                while queue:
                    node = queue.pop()
                    for neighbor in graph[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)
        return visited


