    def countArrangement(self, n: int) -> int:
        dp = [None] * (1 << n)
        def say(mask, pl):
            if pl == 0:
                return 1
            if dp[mask] is not None:
                return dp[mask]
            res = 0
            for i in range(n):
                if not (mask >> i) & 1:
                    if (pl % (i + 1)) == 0 or ((i + 1) % pl) == 0:
                        res += say(mask ^ (1 << i), pl - 1)
            dp[mask] = res
            return res
        return say(0, n)

