    def isPrime(self, n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def diagonalPrime(self, n: int) -> List[int]:
        dp = [0] * (n + 1)
        dp[2] = 1
        for i in range(3, n + 1):
            if self.isPrime(i):
                dp[i] = dp[i - 1] + 1
            else:
                dp[i] = dp[i - 1]
        return dp[n]

