class Solution:
    def minAreaFreeRect(self, points: List[List[int]]) -> float:
        n = len(points)
        min_area = float('inf')
        diagonal_points = defaultdict(list)
        squared_distances = {}

        for i in range(n):
            for j in range(i + 1, n):
                squared_distances[(i, j)] = (points[i][0] - points[j][0]) ** 2 + (points[i][1] - points[j][1]) ** 2

                diagonal_points[points[i][0] + points[j][0], points[i][1] + points[j][1]].append((i, j))

        for diagonal in diagonal_points:
            diagonal_points[diagonal].sort(key=lambda x: squared_distances[x])

            for i in range(len(diagonal_points[diagonal])):
                if i + 1 >= len(diagonal_points[diagonal]):
                    break

                point1 = diagonal_points[diagonal][i]
                point2 = diagonal_points[diagonal][i + 1]

                if squared_distances[point1] != squared_distances[point2]:
                    continue

                area = math.sqrt(squared_distances[point1]) * math.sqrt(squared_distances[point2])
                min_area = min(min_area, area)

        return min_area if min_area != float('inf') else 0

