class Solution:
    def countHighestPeak(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        visited = set()

        def dfs(i, j, visited):
            if (i, j) in visited:
                return
            visited.add((i, j))
            for d in directions:
                ni, nj = i + d[0], j + d[1]
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] < grid[i][j]:
                    dfs(ni, nj, visited)

        res = []
        for i in range(m):
            for j in range(n):
                if grid[i][j] == -1:
                    continue
                cur_visited = set()
                dfs(i, j, cur_visited)
                res.append((len(cur_visited), grid[i][j], (i, j)))
                for x, y in cur_visited:
                    grid[x][y] = -1
        res.sort(reverse=True)
        return res[0][0]

