import sys

def main():
    input = sys.stdin.readline

    n, m = map(int, input().split())

    INF = 1001  # same as original
    # Use list of lists instead of NumPy
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0

    edges = []
    for _ in range(m):
        a, b, w = map(int, input().split())
        a -= 1
        b -= 1
        edges.append((a, b, w))
        if w < d[a][b]:
            d[a][b] = w
            d[b][a] = w

    # Floyd–Warshall
    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            dik = di[k]
            # small optimization: skip if dik is already INF
            if dik == INF:
                continue
            alt_ik = dik
            for j in range(n):
                via = alt_ik + dk[j]
                if via < di[j]:
                    di[j] = via

    # Count edges that are longer than some shortest path
    c = 0
    for a, b, w in edges:
        if d[a][b] < w:
            c += 1

    print(c)

