    def longestConsecutive(self, nums: List[int]) -> int:
        map_set = set(nums)
        current_start = -1
        current_len = 0
        for num in nums:
            if num >= current_start  and num < current_start + current_len:
                continue
            start = num
            count = 1
            while start -1 in map_set:
                start = start -1
                count = count + 1
            end = num
            while end + 1 in map_set:
                end = end + 1
                count = count + 1
            if count > current_len:
                current_len = count
                current_start = start
        return current_len

