class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        self.res = 0
        m, n, todo = len(grid), len(grid[0]), 1
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    x, y = (i, j)
                elif grid[i][j] == 0:
                    todo += 1
        def dfs(x, y, todo):
            if not (0 <= x < m and 0 <= y < n and grid[x][y] >= 0): return
            if grid[x][y] == 2:
                self.res += 1
                return
            grid[x][y] = -2
            dfs(x - 1, y, todo - 1)
            dfs(x, y - 1, todo - 1)
            dfs(x + 1, y, todo - 1)
            dfs(x, y + 1, todo - 1)
            grid[x][y] = 0
        dfs(x, y, todo)
        return self.res

