INF = 10**9 * 15

def main():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    # indices 1..n-1 are candidates for the k-1 chosen positions
    c = range(1, n)

    ans = INF

    for comb in combinations(c, k - 1):
        s = set(comb)  # O(k) build, O(1) membership

        mx = a[0]
        cost = 0

        for i in range(1, n):
            if i in s:
                if a[i] > mx:
                    mx = a[i]
                else:
                    mx += 1
                    cost += mx - a[i]
            else:
                if a[i] > mx:
                    mx = a[i]

        if cost < ans:
            ans = cost

    print(ans)

