def count_first_last_pairs(N: int) -> int:
    # count[x][y] = how many integers in [1, N] have first digit x and last digit y
    count = [[0] * 10 for _ in range(10)]

    for first in range(1, 10):
        # Build the smallest number with first digit = first
        base = first
        if base > N:
            break

        # Extend by adding digits in the middle
        # We consider numbers: first, first?, first??, ... up to N
        while base <= N:
            # For each possible last digit
            for last in range(10):
                num = base + last
                if num > N:
                    break
                # Ensure last digit is indeed 'last'
                if num % 10 == last:
                    count[first][last] += 1

            # Move to next "block" of numbers with same first digit and one more digit
            base *= 10

    ans = 0
    for a in range(1, 10):
        for b in range(1, 10):
            ans += count[a][b] * count[b][a]
    return ans


