class Solution:
    def minDays(self, bloomDay, m, k):
        if m*k>len(bloomDay):
            return -1
        left = min(bloomDay)
        right = max(bloomDay)
        while left<=right:
            mid = (left+right)//2
            adjacency = self.can_cut(bloomDay, k, mid)
            if adjacency>=m:
                right = mid-1
            else:
                left = mid+1
        return left
    def can_cut(self, bloomDay, k, day):
        adjacency = 0
        k_temp = k
        for i in bloomDay:
            if i <= day:
                k_temp -= 1
                if k_temp == 0:
                    adjacency += 1
                    k_temp = k
            else:
                k_temp = k
        return adjacency

