    def maxCoins(self, nums: List[int]) -> int:
        nums = [1] + nums + [1]
        N = len(nums)
        dp1 = [ [0]*N for _ in nums ]
        dp2 = [ [0]*N for _ in nums ]
        for k in range(2,N):
            for left in range(0,N-k):
                right = left+k
                for i in range(left+1,right):
                    dp2[left][right] = max( dp2[left][right], 
                        dp1[left][i] + dp1[i][right] + nums[left]*nums[i]*nums[right] )
                dp1[left][right] = max( dp2[left][i] + dp1[i][right] + nums[left]*nums[i]*nums[right]
                    for i in range(left+1,right) )
        return dp1[0][N-1]

