        visited.add(start)
        step = 0
        while queue:
            n = len(queue)
            for _ in range(n):
                cur = queue.popleft()
                if cur == target:
                    return step
                i = cur // 3
                j = cur % 3
                for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
                    if 0 <= x < 4 and 0 <= y < 3 and cur != x * 3 + y:
                        new = cur
                        new += (x * 3 + y - cur) * dic[board[x][y]]
                        if new not in visited:
                            queue.append(new)
                            visited.add(new)
