class Solution:
    def solve(self, weights, values, N, W, i, j, dp):
        if i > N or j > W:
            return 0
        if dp[i][j] != -1:
            return dp[i][j]

        option1 = option2 = option3 = 0

        if weights[i] <= j:
            option1 = values[i] + self.solve(weights, values, N, j-weights[i], i+1, j, dp)
        option2 = self.solve(weights, values, N, j, i+1, j, dp)
        if weights[i] <= j+1:
            option3 = values[i] + self.solve(weights, values, N, j-weights[i]+1, i+1, j+1, dp)

        dp[i][j] = max(option1, option2, option3)
        return dp[i][j]

    def knapsack(self, weights, values, N, W):
        dp = [[-1 for _ in range(W+1)] for _ in range(N+1)]
        return self.solve(weights, values, N, W, 0, 0, dp)

