class Solution:
    def countHighestPeak(self, isWater: List[List[int]]) -> int:
        m, n = len(isWater), len(isWater[0])
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        ans = [0] * 101
        for i in range(m):
            for j in range(n):
                if isWater[i][j] == 1:
                    continue
                height = -1
                for dx, dy in directions:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < m and 0 <= nj < n and isWater[ni][nj] == 1:
                        height = max(height, isWater[ni][nj])
                if height != -1:
                    ans[height] += 1
        return ans[max(ans)]

