    N = int(input())

    g = []
    for _ in range(N):
        a = int(input())
        t = []
        for _ in range(a):
            x, y = map(int, input().split())
            x -= 1
            t.append((x, y))
        g.append(t)

    ans = 0
    # Enumerate all subsets of honest people as bitmasks: 0..(1<<N)-1
    for mask in range(1 << N):
        ok = True
        for j in range(N):
            # If person j is honest in this mask
            if (mask >> j) & 1:
                for x, y in g[j]:
                    # Check if x's honesty in mask matches y
                    if ((mask >> x) & 1) != y:
                        ok = False
                        break
                if not ok:
