def factorize(num: int) -> dict:
    """素因数分解"""
    from math import sqrt
    from collections import Counter

    d = Counter()
    # 終点はルート切り捨て+1
    for i in range(2, int(sqrt(num)) + 1):
        # 素因数分解：小さい方から割れるだけ割って素数をカウント
        while num % i == 0:
            num //= i
            d[i] += 1
        # 1まで分解したら終了
        if num == 1:
            break
    # 最後に残ったnumは素数(ただし1^1は1^0なので数に入れない)
    if num != 1:
        d[num] += 1
    return d


class FactInvMOD:
    """階乗たくさん使う時用のテーブル準備"""

    def __init__(self, MAX, MOD):
        """MAX：階乗に使う数値の最大以上まで作る"""
        MAX += 1
        self.MAX = MAX
        self.MOD = MOD
        # 階乗テーブル
        factorial = [1] * MAX
        factorial[0] = factorial[1] = 1
        for i in range(2, MAX):
            factorial[i] = factorial[i - 1] * i % MOD
        # 階乗の逆元テーブル
        inverse = [1] * MAX
        # powに第三引数入れると冪乗のmod付計算を高速にやってくれる
        inverse[MAX - 1] = pow(factorial[MAX - 1], MOD - 2, MOD)
        for i in range(MAX - 2, 0, -1):
            # 最後から戻っていくこのループならMAX回powするより処理が速い
            inverse[i] = inverse[i + 1] * (i + 1) % MOD
        self.fact = factorial
        self.inv = inverse

    def nCr(self, n, r):
        """組み合わせの数 (必要な階乗と逆元のテーブルを事前に作っておく)"""
        if n < r:
            return 0
        # 10C7 = 10C3
        r = min(r, n - r)
        # 分子の計算
        numerator = self.fact[n]
        # 分母の計算
        denominator = self.inv[r] * self.inv[n - r] % self.MOD
        return numerator * denominator % self.MOD

    def nPr(self, n, r):
        """順列"""
        if n < r:
            return 0
        return self.fact[n] * self.inv[n - r] % self.MOD

    def nHr(self, n, r):
        """重複組み合わせ"""
        # r個選ぶところにN-1個の仕切りを入れる
        return self.nCr(r + n - 1, r)


