class Solution:
    def solve(self, nums, k, dp):
        if k==0:
            return 0
        if k<0:
            return float('inf')
        if dp[k] is not None:
            return dp[k]
        res = float('inf')
        for i in range(len(nums)):
            if nums[i] <= k:
                res = min(res, self.solve(nums, k-nums[i], dp)+1)
        dp[k] = res
        return res

    def minimumSubsetSum(self, nums, k):
        summ = sum(nums)
        if summ == k:
            return 1
        if summ < k:
            return -1
        dp = [None for _ in range(k+1)]
        ans = self.solve(nums, k, dp)
        if ans == float('inf'):
            return -1
        return ans

