    import sys
    import heapq

    input = sys.stdin.readline

    n, m = map(int, input().split())
    tree = [[] for _ in range(n)]

    for _ in range(m):
        i, j, k = map(int, input().split())
        i -= 1
        j -= 1
        tree[i].append((k, j))
        tree[j].append((k, i))

    ans = 0

    for i in range(n):
        edges_i = tree[i]
        for base, goal in edges_i:
            # seen as Python list instead of numpy array
            seen = [False] * n
            seen[i] = True

            todo = []
            # push neighbors of i with weight < base, excluding the (base, goal) edge
            for w, v in edges_i:
                if w < base and (w, v) != (base, goal):
