# -*- coding: utf-8 -*-

import sys
from sys import stdin

input = stdin.readline


class Graph(object):
    """All-pairs shortest path using Warshall-Floyd."""

    def __init__(self, n, data):
        # Nodes are assumed to be 0..n (inclusive) as in the original code
        self.num_of_nodes = n + 1
        INF = float('inf')

        # Initialize adjacency matrix
        V = self.num_of_nodes
        M = [[INF] * V for _ in range(V)]
        for i in range(V):
            M[i][i] = 0

        # Fill edges
        for d in data:
            r = d[0]
            # d format: [r, k, t1, t2, ...] -> edges r -> ti
            for t in d[2:]:
                M[r][t] = 1

        self.M = M

    def warshallFloyd(self):
        V = self.num_of_nodes
        M = self.M
        INF = float('inf')

        # Standard Floyd–Warshall
        for k in range(V):
            Mk = M[k]
            for i in range(V):
                Mik = M[i][k]
                if Mik == INF:
                    continue
                Mi = M[i]
                for j in range(V):
                    alt = Mik + Mk[j]
                    if alt < Mi[j]:
                        Mi[j] = alt


def main(args):
    n = int(input())
    network = []
    for _ in range(n):
        network.append(list(map(int, input().split())))

    p = int(input())
    packets = []
    for _ in range(p):
        packets.append(list(map(int, input().split())))

    g = Graph(n, network)
    g.warshallFloyd()

    M = g.M
    out_lines = []
    for s, d, v in packets:
        dist = M[s][d]
        if dist < v:
            out_lines.append(str(dist + 1))
        else:
            out_lines.append('NA')

    sys.stdout.write('\n'.join(out_lines) + '\n')


if __name__ == '__main__':
    main(sys.argv[1:])

