class Solution:
    def networkDelay(self, times: List[List[int]], n: int, k: int) -> int:
        dist = [float('inf')] * (n + 1)
        adj = defaultdict(list)
        for t in times:
            adj[t[0]].append([t[1], t[2]])
        dist[k] = 0
        h = []
        heappush(h, (0, k))
        while h:
            d, node = heappop(h)
            if dist[node] < d:
                continue
            for nei, cost in adj[node]:
                if dist[nei] > d + cost:
                    dist[nei] = d + cost
                    heappush(h, (d + cost, nei))
        res = max(dist[1:])
        return res if res < float('inf') else -1

