    def countPalindromicSubsequences(self, s: str) -> int:
        @lru_cache(None)
        def dp(i,j):
            if i>j: return 0
            if i==j: return 1
            res = dp(i+1,j)
            if s[i]==s[j]: res += dp(i+1,j-1)+1
            return res
        return dp(0,len(s)-1)

