        rightCandle = [-1] * 26
        plateCount = [0] * (len(s) + 1)
        for i, ch in enumerate(s):
            rightCandle[ord(ch) - ord('a')] = max(rightCandle[ord(ch) - ord('a')], i)
            plateCount[i + 1] = plateCount[i] + 1
