    def findClosestNode(self, edges: List[int]) -> int:
        n = len(edges)
        # Step 1: Find all ancestors of node 0
        ancestors = [set() for _ in range(n)]
        def complete_ancestors(i):
            if i != 0 and edges[i] != -1:
                ancestors[edges[i]].add(i)
                complete_ancestors(edges[i])
        complete_ancestors(0)
        # Step 2: Find the node with the largest number of ancestors
        max_num_ancestors = max([len(ancestor) for ancestor in ancestors])
        if max_num_ancestors == 1:
            return 0
        else:
            return [i for i in range(n) if len(ancestors[i]) == max_num_ancestors][0]

