class Solution:
    MOD = 1000000007

    @staticmethod
    def factorial(n):
        res = 1
        for i in range(1, n + 1):
            res = (res * i) % Solution.MOD
        return res

    @staticmethod
    def modInverse(x):
        return pow(x, Solution.MOD - 2, Solution.MOD)

    def countAnagrams(self, s, k):
        n = len(s)
        freq = {}
        for i in range(n):
            if s[i] not in freq:
                freq[s[i]] = 0
            freq[s[i]] += 1
        total = 0
        for key in freq:
            total += freq[key] // 2
        if n == 1:
            return (k // 2) % Solution.MOD
        if s[0] == s[-1]:
            total += (k - 1) // 2
        total %= Solution.MOD
        res = 0
        for key in freq:
            res += (Solution.factorial(freq[key]) * Solution.modInverse(freq[key] // 2)) % Solution.MOD
        res %= Solution.MOD
        return (total * k) % Solution.MOD

