class Solution:
    def countAnagrams(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = (fact[i - 1] * i) % MOD
        inv = [1] * (n + 1)
        inv[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n - 1, -1, -1):
            inv[i] = (inv[i + 1] * (i + 1)) % MOD
        def choose(n, r):
            return (fact[n] * inv[r] % MOD) * inv[n - r] % MOD
        ans = 0
        for i in range(n):
            for j in range(i + 1, n):
                if s[i] == s[j]:
                    continue
                k = n - i - 1
                l = n - j - 1
                ans += choose(k, l)
                ans %= MOD
        return ans

class Solution:
    def countAndSay(self, n: int) -> str:
        def say(s):
            i, k = 0, 1
            r = ''
            while i < len(s):
                if s[i] == s[i+k]:
                    k += 1
                else:
                    r += str(k) + s[i]
                    i += k
                    k = 1
            return r
        s = '1'
        for i in range(1, n):
            s = say(s)
        return s

