class UnionFind:
    def __init__(self, n):
        self.n = n
        self.parents = [-1] * n

    def find(self, x):
        parents = self.parents
        while parents[x] >= 0:
            if parents[parents[x]] >= 0:
                parents[x] = parents[parents[x]]  # path halving
            x = parents[x]
        return x

    def union(self, x, y):
