        ans, prev = 0, -1
        for i, c in enumerate(s):
            if c != s[prev]:
                prev = i
                continue
            start, end = prev, i
            while start >= 0 and s[start] != s[prev]:
                start -= 1
            while end < len(s) and s[end] != s[prev]:
                end += 1
            if start != -1 and end != len(s):
                ans += 1
                prev = end
        return ans

