import sys

# Coin values and corresponding prices
VALUES = [200, 300, 500, 1000, 1200, 1500]
PRICES = [380, 550, 850, 1520, 1870, 2244]

MAX_AMOUNT = 10000  # Problem constraint

# Precompute minimum cost for all amounts up to MAX_AMOUNT
INF = 10**18
dp = [INF] * (MAX_AMOUNT + 1)
dp[0] = 0

for v, p in zip(VALUES, PRICES):
    for x in range(v, MAX_AMOUNT + 1):
        if dp[x - v] + p < dp[x]:
            dp[x] = dp[x - v] + p

def solve(amount: int) -> int:
    # Best price using only 200-yen tickets
    best_price = (amount + 199) // 200 * 380
    # If exact combination exists via DP, take the minimum
    if amount <= MAX_AMOUNT and dp[amount] < best_price:
        best_price = dp[amount]
    return best_price

def main(args):
    it = sys.stdin
    for line in it:
        line = line.strip()
        if not line:
            continue
        amount = int(eval(line))  # keep same behavior as original
        if amount == 0:
            break
        print(solve(amount))

if __name__ == '__main__':
    main(sys.argv[1:])

