    def countPalindromicSubsequence(self, s: str) -> int:
        ans, prev = 0, -1
        for i in range(1, len(s)):
            if s[i] == s[i - 1]:
                continue
            curr = s[i:i + 2].find(s[i - 1], i)
            if curr != -1 and curr > prev:
                ans += 1
                prev = curr
        return ans

