INF = 10 ** 8

def main():
    input = stdin.readline

    n, m, r = map(int, input().split())
    l = list(map(int, input().split()))
    # convert to 0-based
    for i in range(r):
        l[i] -= 1

    # initialize distance matrix
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0

    for _ in range(m):
        a, b, c = map(int, input().split())
        a -= 1
        b -= 1
        if c < d[a][b]:
            d[a][b] = c
            d[b][a] = c

    # Floyd–Warshall
    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            dik = di[k]
            # if dik is already INF, skip inner loop
            if dik == INF:
                continue
            for j in range(n):
                # di[j] = min(di[j], di[k] + d[k][j])
                alt = dik + dk[j]
                if alt < di[j]:
