    for perm in permutations(l):
        total = 0
        # early break if already worse than current best
        for i in range(r - 1):
            total += d_local[perm[i]][perm[i + 1]]
            if total >= answer:
                break
        else:
            # only executed if loop wasn't broken
            if total < answer:
                answer = total

    print(answer)

