class Solution:
    def countAnagrams(self, s: str) -> int:
        n = len(s)
        mod = 10**9 + 7
        pow25 = [1] * n
        pow24 = [1] * n
        for i in range(1, n):
            pow25[i] = (pow25[i - 1] * 25) % mod
            pow24[i] = (pow24[i - 1] * 24) % mod
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = (fact[i - 1] * i) % mod
        ans = 0
        for i in range(n):
            for j in range(i + 1, n + 1):
                if s[i] == s[j - 1]:
                    continue
                cur = (pow25[j - i - 1] * fact[i] * fact[n - j]) % mod
                ans = (ans + cur) % mod
        return ans

