from sys import stdin, stdout

MOD = 10**9 + 7

def main():
    rl = stdin.readline
    s = int(rl())

    # dp[x] = number of ways to reach sum x
    dp = [0] * (s + 1)
    dp[0] = 1

    # For each sum, add contributions of adding any d in [3, 2000]
    for curr in range(s + 1):
        if dp[curr] == 0:
            continue
        # next sum ranges from curr+3 to curr+2000, bounded by s
        start = curr + 3
        if start > s:
            continue
        end = min(s, curr + 2000)
        val = dp[curr]
        for nxt in range(start, end + 1):
            dp[nxt] += val
            if dp[nxt] >= MOD:
                dp[nxt] -= MOD

    stdout.write(str(dp[s]))
    stdout.close()

if __name__ == "__main__":
    main()

