import numpy as np

n, m = list(map(int, input().split()))
ab = [list(map(int, input().split())) for i in range(n)]
cd = [list(map(int, input().split())) for i in range(m)]
dist = np.zeros((n, m))
for i in range(n):
    for j in range(m):
        dist[i, j] = abs(ab[i][0] - cd[j][0]) + abs(ab[i][1] - cd[j][1])
for dis in dist:
    print((dis.argmin() + 1))
